package com.bionote.agent.model;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

@Component
@ConditionalOnProperty(name="agent.provider",havingValue="fake",matchIfMissing=true)
public class FakeAgentModelClient implements AgentModelClient {
    private final Deque<Object> script=new ArrayDeque<>(); private final List<AgentModelRequest> requests=new ArrayList<>();private final ObjectMapper json;
    public FakeAgentModelClient(ObjectMapper json){this.json=json;}
    @Override public String provider(){return "fake";} @Override public ModelCapabilities capabilities(){return new ModelCapabilities(true,true);}
    @Override public synchronized AgentModelResponse complete(AgentModelRequest request){requests.add(request);if(script.isEmpty())return deterministic(request);Object next=script.removeFirst();if(next instanceof RuntimeException error)throw error;return (AgentModelResponse)next;}
    public synchronized void script(List<?> values){script.clear();script.addAll(values);requests.clear();}
    public synchronized List<AgentModelRequest> requests(){return List.copyOf(requests);}
    private AgentModelResponse deterministic(AgentModelRequest request){JsonNode task=read(request.messages().get(0).content());String kind=task.path("task").asText();String scenario=task.path("request").path("focus").asText();if("__FAKE_SCENARIO__:timeout".equals(scenario))throw new ModelClientException("AGENT_TIMEOUT","Deterministic fake provider timeout");if("__FAKE_SCENARIO__:unknown-tool".equals(scenario))return AgentModelResponse.tools(List.of(new ModelToolCall("fake-unknown","unregistered_fake_tool",json.createObjectNode())));if("__FAKE_SCENARIO__:invalid-output".equals(scenario))return AgentModelResponse.finish(json.createObjectNode().put("schemaVersion",1));if("__FAKE_SCENARIO__:evidence-invalid".equals(scenario))return AgentModelResponse.finish(invalidEvidenceArtifact(kind,task));List<AgentModelRequest.ModelMessage> toolMessages=request.messages().stream().filter(value->"tool".equals(value.role())).toList();if(toolMessages.isEmpty())return tool(request,"fake-overview","RECORD_SUMMARY".equals(kind)?"get_record_overview":"get_project_overview",json.createObjectNode());if("RECORD_SUMMARY".equals(kind)&&toolMessages.size()==1)return tool(request,"fake-revisions","list_record_revisions",json.createObjectNode());if("PROJECT_PROGRESS".equals(kind)&&toolMessages.size()==1)return tool(request,"fake-records","list_project_records",json.createObjectNode());if("PROJECT_PROGRESS".equals(kind)&&toolMessages.size()==2)return tool(request,"fake-activity","list_project_activity",json.createObjectNode());JsonNode result=read(toolMessages.get(toolMessages.size()-1).content());if("RECORD_SUMMARY".equals(kind)&&toolMessages.size()==2){JsonNode revisionCandidates=result.path("evidenceCandidates");if(revisionCandidates.isArray()&&revisionCandidates.size()>=2){String from=revisionCandidates.get(1).path("revisionId").asText(revisionCandidates.get(1).path("id").asText());String to=revisionCandidates.get(0).path("revisionId").asText(revisionCandidates.get(0).path("id").asText());return tool(request,"fake-diff","compare_record_revisions",json.createObjectNode().put("fromRevisionId",from).put("toRevisionId",to).put("includeTextHunks",false));}}JsonNode candidate=findCandidate(toolMessages);if(candidate==null)return AgentModelResponse.error("AGENT_EVIDENCE_INVALID","Deterministic fake provider received no evidence candidate");var artifact=json.createObjectNode();artifact.put("schemaVersion",1);artifact.put("headline","RECORD_SUMMARY".equals(kind)?"记录证据摘要":"项目进展证据摘要");artifact.put("executiveSummary","本报告由确定性 fake provider 基于只读领域工具生成，用于本地演示和自动化验证。");String statement=statement(kind,result);artifact.set("progress",json.createArrayNode().add(json.createObjectNode().put("id","progress-1").put("statement",statement).set("evidenceRefs",json.createArrayNode().add("e1"))));artifact.set("risks",json.createArrayNode());artifact.set("nextActions",json.createArrayNode().add(json.createObjectNode().put("id","action-1").put("statement","请由项目成员结合原始记录和审核意见继续复核。").put("basis","MODEL_SUGGESTION").set("evidenceRefs",json.createArrayNode())));var evidence=(com.fasterxml.jackson.databind.node.ObjectNode)candidate.deepCopy();evidence.put("ref","e1");artifact.set("evidence",json.createArrayNode().add(evidence));artifact.set("limitations",json.createArrayNode().add("fake provider 仅用于确定性本地验证，不替代真实模型质量评估。"));JsonNode requestNode=task.path("request");artifact.set("period",json.createObjectNode().put("start",requestNode.path("periodStart").asText("unknown")).put("end",requestNode.path("periodEnd").asText("unknown")));return AgentModelResponse.finish(artifact);}
    private JsonNode invalidEvidenceArtifact(String kind,JsonNode task){var artifact=json.createObjectNode();artifact.put("schemaVersion",1).put("headline","Fake invalid evidence").put("executiveSummary","This deterministic scenario must be rejected by EvidenceValidator.");artifact.set("progress",json.createArrayNode().add(json.createObjectNode().put("id","progress-1").put("statement","Unsupported statement").set("evidenceRefs",json.createArrayNode().add("e1"))));artifact.set("risks",json.createArrayNode());artifact.set("nextActions",json.createArrayNode().add(json.createObjectNode().put("id","action-1").put("statement","Review the failure").put("basis","MODEL_SUGGESTION").set("evidenceRefs",json.createArrayNode())));String type="RECORD_SUMMARY".equals(kind)?"RECORD":"PROJECT";artifact.set("evidence",json.createArrayNode().add(json.createObjectNode().put("ref","e1").put("type",type).put("id","00000000-0000-0000-0000-000000000000").put("label","hallucinated fake evidence")));artifact.set("limitations",json.createArrayNode());JsonNode requestNode=task.path("request");artifact.set("period",json.createObjectNode().put("start",requestNode.path("periodStart").asText("unknown")).put("end",requestNode.path("periodEnd").asText("unknown")));return artifact;}
    private AgentModelResponse tool(AgentModelRequest request,String id,String name,JsonNode arguments){if(request.tools().stream().noneMatch(value->value.name().equals(name)))return AgentModelResponse.error("AGENT_TOOL_NOT_ALLOWED","Deterministic fake provider requires "+name);return AgentModelResponse.tools(List.of(new ModelToolCall(id,name,arguments)));}
    private JsonNode findCandidate(List<AgentModelRequest.ModelMessage> messages){for(int index=messages.size()-1;index>=0;index--){JsonNode candidates=read(messages.get(index).content()).path("evidenceCandidates");if(candidates.isArray()&&!candidates.isEmpty())return candidates.get(0);}return null;}
    private String statement(String kind,JsonNode payload){JsonNode data=payload.path("data");if("RECORD_SUMMARY".equals(kind)){if(data.has("summary")){JsonNode summary=data.path("summary");return "已比较两个正式提交版本：新增 "+summary.path("added").asInt()+"、删除 "+summary.path("removed").asInt()+"、修改 "+summary.path("modified").asInt()+" 个领域 section。";}String status=data.path("status").asText("UNKNOWN");int revisions=data.path("revisionCount").asInt(0);return "记录当前状态为 "+status+"，已读取到 "+revisions+" 个正式提交版本；该状态不代表实验结果成功。";}if(data.isArray())return "报告时间窗口内读取到 "+data.size()+" 条已脱敏项目活动；活动事实均来自审计投影。";JsonNode counts=data.path("recordCountsByStatus");if(counts.isMissingNode())counts=data.path("recordCounts");return "已从项目只读概览读取状态分布："+compact(counts)+"；已完成状态不等于实验结果成功。";}
    private String compact(JsonNode value){try{return json.writeValueAsString(value);}catch(Exception e){return "{}";}}
    private JsonNode read(String value){try{return json.readTree(value);}catch(Exception e){return json.createObjectNode();}}
}
